import boto3
from typing import List, Dict

def extract_table_layout(file_bytes: bytes) -> List[Dict]:
    """
    Extracts table cells and row structure from a document using Amazon Textract.

    Args:
        file_bytes (bytes): The document file bytes (e.g., PDF, image).

    Returns:
        List[Dict]: A list of dictionaries representing tables with rows and cells.
    """
    # Initialize Textract client
    client = boto3.client('textract')

    # Start Textract analysis
    response = client.start_document_text_detection(Document={'Bytes': file_bytes})
    job_id = response['JobId']

    # Wait for job completion
    while True:
        result = client.get_document_text_detection(JobId=job_id)
        if result['JobStatus'] == 'SUCCEEDED':
            break

    # Extract text and layout information
    blocks = result['Blocks']
    tables = [block for block in blocks if block['BlockType'] == 'TABLE']
    cells = []

    for table in tables:
        rows = {row['Id']: [] for row in table['Relationships'][0]['Ids']}
        for relationship in table['Relationships']:
            if relationship['Type'] == 'CHILD':
                for child_id in relationship['Ids']:
                    child_block = next(block for block in blocks if block['Id'] == child_id)
                    if child_block['BlockType'] == 'CELL':
                        rows[child_block['RowIndex']].append(child_block['Text'])

        for row_index, row_cells in rows.items():
            cells.append({
                'row_index': row_index,
                'cells': row_cells
            })

    return cells
